10:     /** 校验并规范化基础地址；允许本地模型服务，禁止把密钥放入 URL。 */
11:     public static String normalize(String value) {
12:         if (value == null || value.isBlank()) return null;
13:         try {
14:             URI uri = URI.create(value.trim());
15:             if (!("https".equalsIgnoreCase(uri.getScheme()) || "http".equalsIgnoreCase(uri.getScheme()))
16:                     || uri.getHost() == null || uri.getRawUserInfo() != null
17:                     || uri.getRawQuery() != null || uri.getRawFragment() != null) {
18:                 throw new IllegalArgumentException();
19:             }
20:             String result = value.trim().replaceAll("/+$", "");
21:             if (result.endsWith("/chat/completions") || result.endsWith("/messages")) {
22:                 throw new IllegalArgumentException();
23:             }
24:             return result;
25:         } catch (IllegalArgumentException exception) {
26:             throw new IllegalArgumentException("API 地址须为 HTTP(S) 基础地址，不含凭据、查询参数或 /chat/completions、/messages 后缀");
27:         }
28:     }
29: 
30:     /** 自定义请求仅支持 OpenAI Chat Completions 与 Anthropic Messages 协议。 */
31:     public static String protocol(String value) {
32:         String protocol = value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
33:         if (!protocol.equals("openai") && !protocol.equals("anthropic")) {
34:             throw new IllegalArgumentException("请选择 OpenAI 或 Anthropic 请求格式");
35:         }
36:         return protocol;
37:     }
38: 
39:     /** Anthropic SDK 自行追加 /v1/messages，避免用户填写 /v1 后重复拼接。 */
40:     public static String anthropicBaseUrl(String value) {
41:         String baseUrl = normalize(value);
42:         return baseUrl != null && baseUrl.endsWith("/v1")
43:                 ? baseUrl.substring(0, baseUrl.length() - 3) : baseUrl;
44:     }
45: }

